class Book
    private define borrowed as integer;

    method constructor()
        this.borrowed <- 0;
    endMethod

    public method Borrow()
        this.borrowed <- 1;
    endMethod

    public method GiveBack()
        this.borrowed <- 0;
    endMethod

    public method IsBorrowed() as integer
        return this.borrowed;
    endMethod
endClass

algorithm RunBook
    define borrow as integer;
    define giveBack as integer;
    define book as Book;
    read borrow;
    read giveBack;
    book <- new Book();
    if borrow = 1 then
        book.Borrow();
    endIf
    if giveBack = 1 then
        book.GiveBack();
    endIf
    write book.IsBorrowed();
endAlgorithm
